import{_ as r,l as i,o as e,c as l,v as o,p as d,x as n,d as p,i as s,S as c}from"./chunks/framework.InCnrqk-.js";const v=JSON.parse('{"title":"过度自信","description":"","frontmatter":{"title":"过度自信","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/overconfidence.md","filePath":"econ/overconfidence.md","lastUpdated":1789023840000}'),h={name:"econ/overconfidence.md"};function E(f,a,A,B,m,_){const t=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="过度自信" tabindex="-1">过度自信 <a class="header-anchor" href="#过度自信" aria-label="Permalink to &quot;过度自信&quot;">​</a></h1><div class="epigraph"><p>人对自己的知识给出过窄的置信区间，对相对排名给出过高的位置——错的是信念，不一定是 $v$。</p><footer>—— Alpert and Raiffa 的校准；Svenson, Acta Psychologica 1981；Odean, Journal of Finance 1998, 1999</footer></div><p><a href="/econ/endowment-effect">上一课</a>动的是参考点上的评价。本课缺口换成信念：过度精确、过高估计、过优定位。不重写 \\(\\lambda\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>前景理论可以在正确概率上扭曲权重。过度自信是概率本身错了：置信区间覆盖真值的频率低于名义水平（Alpert 与 Raiffa 的校准）；多数人认为自己驾驶水平高于中位数（Svenson, 1981）。Odean（1998, 1999）把过度自信接到交易：人高估私有信号精度，成交量上升，事后平均亏损。Daniel、Hirshleifer 与 Subrahmanyam 的定价模型是后单元；本课先钉微观信念偏差。</p><p>缺口是在已有期望效用或前景理论上，把信念从客观 \\(p\\) 换成过度精确的 \\(\\hat p\\)，而不是再定义效用。</p><p><span class="marginnote">Moore 与 Healy 区分三种过度自信。交易量故事主要用过度精确：方差低估，而不是均值盲目乐观。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>校准测验：让人给出 90% 区间，看命中率。相对定位：让人报百分位。市场：比较换手与随后收益。本课不估计知情交易概率——那是微观结构。家庭侧：过度自信降低分散、提高个股集中、提高参与但伤害净收益。</p>',9)),(e(),d(c,null,{default:n(()=>[s(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E8%AF%84%E4%BB%B7%3A%20v%20%E4%B8%8E%20lambda%22%5D%20--%3E%20BEL%5B%22%E4%BF%A1%E5%BF%B5%3A%20%E7%B2%BE%E5%BA%A6%E8%A2%AB%E9%AB%98%E4%BC%B0%22%5D%0A%20%20BEL%20--%3E%20CAL%5B%22%E6%A0%A1%E5%87%86%E5%A4%B1%E8%B4%A5%3A%20%E5%8C%BA%E9%97%B4%E8%BF%87%E7%AA%84%22%5D%0A%20%20BEL%20--%3E%20TR%5B%22%E6%8D%A2%E6%89%8B%E4%B8%8A%E5%8D%87%2C%20%E5%87%80%E6%94%B6%E7%9B%8A%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是后验过窄。贝叶斯更新若把信号精度设得太高，私有信息被过度加权，人愿意和别人交易。总交易量超过理性差异信念所能解释的水平。这与<a href="/econ/emh">EMH</a>的联合假说不同：这里连主观概率的校准都失败，不只是 alpha 的风险调整。现时偏差改的是贴现；过度自信改的是条件分布。</p><p>自我归因（赢了归技能、输了归噪声）使过度自信不被数据消灭，DHS 课再用。</p><p>校准失败与概率加权要分开：加权是明知 \\(p=0.01\\) 仍当 0.05 用；过度精确是把 90% 区间画得像 50%。Odean 的账户证据是换手与随后收益的负相关，不是盘口。主干 <a href="/econ/emh">EMH</a> 的弱式针对历史价格；过度自信交易者可以制造成交量，价格是否可预测仍要联合一个风险模型。本课只钉信念输入先错了。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>难任务上过度自信、易任务上可能不自信。选择进入金融的人可能本身更过度自信，样本不是随机家庭。本课不把所有高换手写成过度自信：再平衡、税收、流动性需求同样产生交易。也不写限价单的排队策略。</p><p>后课默认：过度自信是信念校准失败；启发式是生成这些信念的心理捷径。</p><p>过度精确把置信区间画窄，私有信号被过度加权，换手上升。动的是 \\(\\hat p\\)，不是 \\(v\\)。</p><p>自我归因让数据难以消灭误设，DHS 把它写成价格动态。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>过度精确使置信区间过窄，交易与集中度上升。</li><li>动的是 \\(\\hat p\\)，不是 \\(v\\)；与损失厌恶分工。</li><li>Odean：高换手家庭事后平均表现更差。</li><li>难任务上更过度自信，易任务上可能相反。</li><li>高换手还有再平衡与税收，不能全部归因。</li><li>出处：Alpert and Raiffa；Svenson 1981；Odean, <em>JF</em> 1998, 1999。</li></ul>',11))])}const b=r(h,[["render",E]]);export{v as __pageData,b as default};
